// Secure application with improved error handling and input validation
const express = require('express');
const app = express();

// Security middleware - basic setup
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Simple input validation middleware
const validateHealthRequest = (req, res, next) => {
  // Check for unexpected query parameters
  const allowedParams = []; // No parameters expected for health endpoint
  const receivedParams = Object.keys(req.query);

  if (receivedParams.length > 0) {
    return res.status(400).json({
      error: 'Unexpected query parameters',
      received: receivedParams,
      expected: allowedParams
    });
  }
  next();
};

const validateUsersRequest = (req, res, next) => {
  // Validate query parameters for users endpoint
  const allowedParams = ['limit', 'offset'];
  const receivedParams = Object.keys(req.query);

  const unexpectedParams = receivedParams.filter(param => !allowedParams.includes(param));

  if (unexpectedParams.length > 0) {
    return res.status(400).json({
      error: 'Unexpected query parameters',
      unexpected: unexpectedParams,
      allowed: allowedParams
    });
  }

  // Validate limit parameter if provided
  if (req.query.limit) {
    const limit = parseInt(req.query.limit);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be a number between 1 and 100'
      });
    }
  }

  // Validate offset parameter if provided
  if (req.query.offset) {
    const offset = parseInt(req.query.offset);
    if (isNaN(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        message: 'Offset must be a non-negative number'
      });
    }
  }

  next();
};

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Generic error response - don't expose internal details
  res.status(500).json({
    error: 'Internal server error',
    message: 'Something went wrong. Please try again later.'
  });
});

// Health endpoint with validation
app.get('/health', validateHealthRequest, (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Log the error but don't expose details
    console.error('Health endpoint error:', error);
    res.status(500).json({ 
      status: 'error',
      message: 'Service unavailable'
    });
  }
});

// Users endpoint with validation
app.get('/users', validateUsersRequest, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if parameters provided
    let result = users;
    const limit = req.query.limit ? parseInt(req.query.limit) : null;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;

    if (limit !== null) {
      result = users.slice(offset, offset + limit);
    }

    res.json({
      data: result,
      total: users.length,
      limit: limit,
      offset: offset,
      hasMore: offset + (limit || users.length) < users.length
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to retrieve users',
      message: 'Please try again later'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl,
    method: req.method
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

