// User creation endpoint with robust input validation
app.post('/users', [
  // Validate request body
  body('name')
    .trim()
    .isLength({ min: 2, max: 50 })
    .withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z\s]+$/)
    .withMessage('Name can only contain letters and spaces'),

  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Must provide a valid email address'),

  body('role')
    .optional()
    .isIn(['user', 'admin', 'moderator'])
    .withMessage('Role must be one of: user, admin, moderator'),
], async (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user data',
        errors: errors.array(),
        timestamp: new Date().toISOString(),
      });
    }

    const { name, email, role = 'user' } = req.body;

    // Additional business logic validation
    if (email.includes('admin') && role !== 'admin') {
      return res.status(400).json({
        status: 'error',
        message: 'Email containing "admin" must have admin role',
        timestamp: new Date().toISOString(),
      });
    }

    // Simulate database operation
    const newUser = {
      id: Math.floor(Math.random() * 1000) + 3, // Generate unique ID
      name: name.trim(),
      email: email.toLowerCase(),
      role,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      status: 'success',
      message: 'User created successfully',
      data: newUser,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('User creation error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error while creating user',
      timestamp: new Date().toISOString(),
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found',
    path: req.originalUrl,
    timestamp: new Date().toISOString(),
  });
});

// Global error handler (must be last middleware)
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : error.message;

  res.status(error.status || 500).json({
    status: 'error',
    message,
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack }),
    timestamp: new Date().toISOString(),
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit the process here
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, exit the process to avoid undefined behavior
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

