// Secure Express.js application with proper error handling and input validation
const express = require('express');
const app = express();

// Basic security middleware
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Request size limiting
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateName = (name) => {
  return typeof name === 'string' && name.length >= 2 && name.length <= 50 && /^[a-zA-Z\s]+$/.test(name);
};

// Enhanced health endpoint with error handling
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    };

    res.status(200).json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Enhanced users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Limit must be a number between 1 and 100',
        timestamp: new Date().toISOString()
      });
    }

    if (isNaN(offset) || offset < 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Offset must be a positive number',
        timestamp: new Date().toISOString()
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination simulation
    const paginatedUsers = users.slice(offset, offset + limit);

    res.status(200).json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found',
    path: req.originalUrl,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  res.status(500).json({
    status: 'error',
    message: 'Internal server error',
    timestamp: new Date().toISOString()
  });
});

// Use environment variable for port with fallback
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

