// Improved application with enhanced security practices
const express = require('express');
const helmet = require('helmet'); // Security middleware
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS configuration
const { body, validationResult, query } = require('express-validator'); // Input validation
const morgan = require('morgan'); // Logging

const app = express();

// Security middleware setup
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"]
    }
  }
}));

// Rate limiting configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// CORS configuration - be specific about allowed origins
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true
}));

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Logging middleware
app.use(morgan('combined'));

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak sensitive error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Something went wrong. Please try again later.'
    });
  }

  res.status(500).json({ 
    error: 'Internal Server Error',
    message: err.message,
    stack: err.stack
  });
});

// Simple error handler for async routes
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Validation error formatter
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      details: errors.array()
    });
  }
  next();
};

// Health check endpoint with input validation
app.get('/health', 
  [
    query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
  ],
  handleValidationErrors,
  (req, res) => {
    const { detailed } = req.query;

    const response = { 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (detailed === 'true') {
      response.system = {
        memory: process.memoryUsage(),
        platform: process.platform,
        nodeVersion: process.version
      };
    }

    res.json(response);
  }
);

// In-memory user data store (for demo purposes)
let users = [
  { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: new Date('2023-01-01') },
  { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: new Date('2023-01-02') }
];

// Get users with pagination and filtering
app.get('/users',
  [
    query('page').optional().isInt({ min: 1 }).withMessage('page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
    query('search').optional().isLength({ max: 50 }).withMessage('search term too long'),
    query('sort').optional().isIn(['name', 'email', 'createdAt']).withMessage('invalid sort field')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    try {
      const { page = 1, limit = 10, search, sort = 'name' } = req.query;

      let filteredUsers = [...users];

      // Apply search filter if provided
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = filteredUsers.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply sorting
      filteredUsers.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const paginatedUsers = filteredUsers.slice(startIndex, startIndex + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          totalItems: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit)
        }
      });

    } catch (error) {
      console.error('Error fetching users:', error);
      throw error; // Let the error handler catch it
    }
  })
);

// Get specific user by ID
app.get('/users/:id',
  [
    query('id').isInt({ min: 1 }).withMessage('ID must be a positive integer')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    try {
      const userId = parseInt(req.params.id);
      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'Not Found',
          message: `User with ID ${userId} not found`
        });
      }

      res.json(user);

    } catch (error) {
      console.error('Error fetching user:', error);
      throw error;
    }
  })
);

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Process terminated');
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

