// Enhanced Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const expressValidation = require('express-validation');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet()); // Sets various security headers
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded payload

// CORS configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Input validation schemas
const healthCheckSchema = {
  query: {
    detailed: Joi.boolean().optional()
  }
};

const usersQuerySchema = {
  query: {
    page: Joi.number().integer().min(1).optional(),
    limit: Joi.number().integer().min(1).max(100).optional()
  }
};

// Routes with proper validation
app.get('/health', expressValidation.validate(healthCheckSchema), (req, res) => {
  try {
    const detailed = req.query.detailed === 'true';
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (detailed) {
      response.memory = process.memoryUsage();
      response.env = process.env.NODE_ENV || 'development';
    }

    res.json(response);
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to process health check request'
    });
  }
});

app.get('/users', expressValidation.validate(usersQuerySchema), (req, res) => {
  try {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    // Validate numeric inputs (additional protection)
    if (isNaN(page) || isNaN(limit)) {
      return res.status(400).json({
        error: 'Invalid parameters',
        message: 'Page and limit must be valid numbers'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination simulation
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve user data'
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Error:', error);

  if (error instanceof expressValidation.ValidationError) {
    // Validation error from express-validation
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details
    });
  }

