    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  const errors = [];
  const warnings = [];

  // Check required environment variables
  requiredEnvVars.forEach(envVar => {
    if (!process.env[envVar]) {
      errors.push(`Missing required environment variable: ${envVar}`);
    }
  });

  // Check for synthetic/canary values in production
  if (process.env.NODE_ENV === 'production') {
    optionalEnvVars.forEach(envVar => {
      if (process.env[envVar] && process.env[envVar].includes('CANARY')) {
        warnings.push(`Potential synthetic value detected in ${envVar} in production environment`);
      }
    });
  }

  return { errors, warnings };
};

// Security checks for environment variables
const securityChecks = () => {
  const checks = [];

  // Check for common security issues
  if (process.env.NODE_ENV === 'production' && process.env.DEBUG) {
    checks.push({
      level: 'warning',
      message: 'DEBUG environment variable set in production - this may expose sensitive information'
    });
  }

  // Check for default ports in production
  if (process.env.NODE_ENV === 'production' && process.env.PORT === '3000') {
    checks.push({
      level: 'info',
      message: 'Using default port 3000 in production - consider using standard HTTP/HTTPS ports'
    });
  }

  return checks;
};

module.exports = {
  validateEnvironment,
  securityChecks
};

