// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security Middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array(),
      message: 'Validation failed'
    });
  }
  next();
};

// Health endpoint with improved error handling
app.get('/health', (req, res, next) => {
  try {
    // Simulate potential error for demonstration
    if (Math.random() < 0.1) { // 10% chance to simulate error
      throw new Error('Health check failed randomly');
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error); // Pass error to error handling middleware
  }
});

// Users endpoint with input validation
app.get('/users', [
  // Validate query parameters
  body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
], validateRequest, (req, res, next) => {
  try {
    const { page = 1, limit = 10 } = req.query;

    // Ensure numerical values after validation
    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Simple pagination simulation
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = startIndex + limitNum;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length,
        totalPages: Math.ceil(users.length / limitNum)
      }
    });
  } catch (error) {
    next(error);
  }
});

// Example of POST endpoint with robust validation
app.post('/users', [
  // Strict input validation
  body('name')
    .trim()
    .isLength({ min: 2, max: 50 })
    .withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z\s]+$/)
    .withMessage('Name can only contain letters and spaces'),

  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Must be a valid email address'),

  body('age')
    .optional()
    .isInt({ min: 0, max: 120 })
    .withMessage('Age must be between 0 and 120'),

], validateRequest, (req, res, next) => {
  try {
    const { name, email, age } = req.body;

    // Sanitize and process data
    const sanitizedUser = {
      name: name.trim(),
      email: email.toLowerCase(),
      age: age ? parseInt(age) : null,
      createdAt: new Date().toISOString()
    };

    // In real application, save to database here
    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: sanitizedUser
    });
  } catch (error) {
    next(error);
  }
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  console.error('Error:', error);

  // Don't leak stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  let errorResponse = {
    success: false,
    message: isProduction ? 'Something went wrong' : error.message,
    ...(!isProduction && { stack: error.stack })
  };

  // Handle specific error types
  if (error.name === 'ValidationError') {
    errorResponse.message = 'Validation failed';
    errorResponse.errors = error.errors;
    return res.status(400).json(errorResponse);
  }

  if (error.code === 'LIMIT_UNEXPECTED_FILE') {
    errorResponse.message = 'Too many files uploaded';
    return res.status(400).json(errorResponse);
  }

  // Default to 500 server error
  res.status(500).json(errorResponse);
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    message: 'Route not found',
    path: req.originalUrl
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

const server = app.listen(3000, () => {
  console.log('Secure server running on port 3000');
});

module.exports = app;

